INSERT INTO `forums` VALUES (1,'General Discussion','This is the place for conversation about all things GOODBLOX. Posts not pertaining to GOODBLOX will be mercilessly pruned by our crack squad of moderators.',10758,100154,24,'2026-05-15 15:54:00','GOODBLOX'),(2,'Creations Gallery','Discuss your GOODBLOX creations and share the secrets of your success. Post requests for help building and scripting here.',3862,19600,0,'2026-05-10 11:54:46','GOODBLOX'),(3,'Suggestions, Feedback, and Ideas','Do you have a suggestion for how to make GOODBLOX better? Share your feedback here.',1461,9951,0,'2026-05-10 11:54:46','GOODBLOX'),(4,'Off Topic','Feel like talking about stuff other than GOODBLOX? Post here.',4892,65777,84,'2026-05-16 13:12:34','GOODBLOX'),(5,'Building Help','Learn the ins and outs of building structures in GOODBLOX here! Share your techniques with other builders, discuss designs, and draft plans.',1791,7567,0,'2026-05-10 11:54:46','Help Center'),(6,'Scripting Help','Need help with a script you are writing? Need to edit an existing script? Want to share your programming skills? For advanced GOODBLOX users.',1997,10049,0,'2026-05-10 11:54:46','Help Center'),(7,'Technical Problems and Bug Reports','Are you having trouble installing or upgrading GOODBLOX? Account troubles? Website problems? Have you found a bug? Post here!',3915,18682,86,'2026-05-10 20:15:38','Help Center'),(8,'Role-Playing','Does your GOODBLOXian want to fly to the moon? Command a ship? Lay siege to a castle? Start a role-playing thread here.',309,5867,0,'2026-05-10 11:54:46','Fun'),(9,'Rate My GOODBLOXian','Show the world of GOODBLOX your character. Get feedback on your outfit.',791,4339,57,'2026-05-10 18:18:29','Fun'),(10,'Sports','Show off your GOODBLOX athlete. Or just hang out with other GOODBLOX fans.',104,1004,0,'2026-05-10 11:54:46','Entertainment'),(11,'Music','Does your GOODBLOXian rock? Let people know. Or just talk about your favorite bands.',203,1375,0,'2026-05-10 11:54:46','Entertainment'),(12,'Movies/TV/Books','Does your GOODBLOXian belong on the silver screen, or in the pages of a novel? Show off your GOODBLOX movie star, discuss your favorite TV series, films, and the books you love.',204,1563,114,'2026-05-17 17:40:44','Entertainment');
/*!40000 ALTER TABLE `forums` ENABLE KEYS */;
